// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport java.util.Calendarimport java.util.Localeimport java.util.concurrent.TimeUnit/** * NOUS — Time Parser (Module 14 v1.2 — Step 14.5). * * Lightweight natural-language time + duration parser for the productivity stack. * * ## Supported Time Formats * * | Format | Example | Meaning | * |--------|---------|---------| * | "H:mm AM/PM" | "7:00 AM" | 7:00 AM today (or tomorrow if past) | * | "H AM/PM" | "7 AM" | 7:00 AM today (or tomorrow if past) | * | "HH:mm" (24h) | "19:00" | 19:00 today (or tomorrow if past) | * | "H:mm" (12h) | "7:00" | 7:00 AM today (or tomorrow if past) | * | "in N <unit>" | "in 2 hours" | 2 hours from now | * | "in Nmin" | "in 30min" | 30 minutes from now | * | "tomorrow H:mm AM/PM" | "tomorrow 3 PM" | 3 PM tomorrow | * | "tomorrow HH:mm" | "tomorrow 15:00" | 15:00 tomorrow | * * ## Supported Duration Formats * * | Format | Example | Meaning | * |--------|---------|---------| * | "N hours" / "N hour" / "Nh" | "1 hour", "2 hours", "2h" | N hours | * | "N minutes" / "N minute" / "Nmin" / "Nm" | "10 minutes", "10m" | N minutes | * | "N seconds" / "N second" / "Ns" | "30 seconds", "30s" | N seconds | * * ## India-aware (Hinglish) * * | Format | Example | Meaning | * |--------|---------|---------| * | "N baje" | "7 baje" | 7:00 AM today (or tomorrow if past) | * | "N baje AM/PM" | "7 baje AM" | 7:00 AM today | * | "shaam N baje" | "shaam 7 baje" | 7:00 PM today | * | "kal N baje" | "kal 3 baje" | 3:00 PM tomorrow | * * ## Limitations * * This is a SIMPLE regex-based parser, not an NLU. It covers the most common * patterns users say to a voice assistant. For complex queries ("next Tuesday * at 3 PM"), the Brain's NLU layer should extract the time slot before * calling [ProductivityFacade]. */object TimeParser {    private const val TAG = "TimeParser"    /**     * Parse a time string to epoch milliseconds.     *     * @return epoch ms, or null if parsing failed.     */    fun parseTimeToEpochMs(input: String): Long? {        val s = input.trim().lowercase(Locale.ROOT)        if (s.isBlank()) return null        // Try "in N <unit>" first (relative time from now).        parseRelativeTime(s)?.let { return it }        // Try "parso N baje" (day after tomorrow at N, Hindi).        parseParsoBaje(s)?.let { return it }        // Try "kal subah N baje" (tomorrow morning at N, Hindi).        parseKalSubahBaje(s)?.let { return it }        // Try "shaam ko N baje" (evening at N, Hindi — variant).        parseShaamKoBaje(s)?.let { return it }        // Try "kal N baje" (tomorrow at N, Hindi/Hinglish).        parseKalBaje(s)?.let { return it }        // Try "tomorrow <time>".        parseTomorrowTime(s)?.let { return it }        // Try "shaam N baje" (evening at N, Hindi/Hinglish).        parseShaamBaje(s)?.let { return it }        // Try "N baje" (today at N, Hindi/Hinglish).        parseBaje(s)?.let { return it }        // Try standard time formats (12h / 24h).        parseStandardTime(s)?.let { return it }        return null    }    /**     * Parse a time string to a [TimeParseResult] (sealed — distinguishes     * Success / Ambiguous / Failed).     *     * Strategy §13: "TimeParser returns TimeParseResult: Success (epoch millis),     * AMBIGUOUS ('7am or 7pm?'), FAILED".     *     * Audit Task ID: audit-m13-productivity P1 — was returning `Long?`.     */    fun parseTime(input: String): TimeParseResult {        val result = parseTimeToEpochMs(input)        return when {            result != null -> TimeParseResult.Success(result)            // Heuristic: if input has a bare hour without AM/PM and hour is            // ambiguous (1-11), mark as AMBIGUOUS.            isAmbiguousHour(input) -> TimeParseResult.Ambiguous(                "Is that $input AM or PM? Please specify.",            )            else -> TimeParseResult.Failed("Could not parse time: '$input'")        }    }    /** True if input is a bare hour (no AM/PM) in the ambiguous range 1-11. */    private fun isAmbiguousHour(input: String): Boolean {        val s = input.trim().lowercase(Locale.ROOT)        // Match "7", "7:00", "7 baje" without AM/PM suffix.        val match = Regex("""^(\d{1,2})(?::\d{2})?\s*(?:baje)?$""").find(s) ?: return false        val hour = match.groupValues[1].toIntOrNull() ?: return false        return hour in 1..11    }    /**     * Parse a duration string to milliseconds.     *     * @return duration ms, or null if parsing failed.     */    fun parseDurationToMs(input: String): Long? {        val s = input.trim().lowercase(Locale.ROOT)        if (s.isBlank()) return null        // Try "N hours" / "N hour" / "Nh".        Regex("""^(\d+)\s*(?:hours?|h)$""").find(s)?.let {            val n = it.groupValues[1].toLongOrNull() ?: return null            return TimeUnit.HOURS.toMillis(n)        }        // Try "N minutes" / "N minute" / "Nmin" / "Nm".        Regex("""^(\d+)\s*(?:minutes?|mins?|m)$""").find(s)?.let {            val n = it.groupValues[1].toLongOrNull() ?: return null            return TimeUnit.MINUTES.toMillis(n)        }        // Try "N seconds" / "N second" / "Ns".        Regex("""^(\d+)\s*(?:seconds?|secs?|s)$""").find(s)?.let {            val n = it.groupValues[1].toLongOrNull() ?: null            if (n != null) return TimeUnit.SECONDS.toMillis(n)        }        // Try plain integer (assume minutes).        s.toLongOrNull()?.let {            return TimeUnit.MINUTES.toMillis(it)        }        return null    }    // ─── Internal parsers ─────────────────────────────────────────────────    /** Parse "in N <unit>" (e.g., "in 2 hours", "in 30 min"). */    private fun parseRelativeTime(s: String): Long? {        val match = Regex("""^in\s+(\d+)\s*(hours?|h|minutes?|mins?|m|seconds?|secs?|s)$""").find(s)            ?: return null        val n = match.groupValues[1].toLongOrNull() ?: return null        val unit = match.groupValues[2]        val durationMs = when {            unit.startsWith("h") -> TimeUnit.HOURS.toMillis(n)            unit.startsWith("m") -> TimeUnit.MINUTES.toMillis(n)            unit.startsWith("s") -> TimeUnit.SECONDS.toMillis(n)            else -> return null        }        return System.currentTimeMillis() + durationMs    }    /** Parse "kal N baje" (tomorrow at N, Hindi). */    private fun parseKalBaje(s: String): Long? {        val match = Regex("""^kal\s+(\d{1,2})(?::(\d{2}))?\s*(?:baje)?(?:\s*(am|pm))?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        val ampm = match.groupValues[3].ifBlank { if (hour in 6..11) "am" else "pm" }        return tomorrowAt(hour, minute, ampm)    }    /** Parse "parso N baje" (day after tomorrow at N, Hindi). */    private fun parseParsoBaje(s: String): Long? {        val match = Regex("""^parso\s+(\d{1,2})(?::(\d{2}))?\s*(?:baje)?(?:\s*(am|pm))?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        val ampm = match.groupValues[3].ifBlank { if (hour in 6..11) "am" else "pm" }        return dayAfterTomorrowAt(hour, minute, ampm)    }    /** Parse "kal subah N baje" (tomorrow morning at N, Hindi). */    private fun parseKalSubahBaje(s: String): Long? {        val match = Regex("""^kal\s+subah\s+(\d{1,2})(?::(\d{2}))?\s*(?:baje)?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        return tomorrowAt(hour, minute, "am")    }    /** Parse "shaam ko N baje" (evening at N, Hindi — variant with "ko"). */    private fun parseShaamKoBaje(s: String): Long? {        val match = Regex("""^shaam\s+ko\s+(\d{1,2})(?::(\d{2}))?\s*(?:baje)?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        return todayAt(hour, minute, "pm") ?: tomorrowAt(hour, minute, "pm")    }    /** Parse "tomorrow <time>". */    private fun parseTomorrowTime(s: String): Long? {        val match = Regex("""^tomorrow\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        val ampm = match.groupValues[3].ifBlank { if (hour in 6..11) "am" else "pm" }        return tomorrowAt(hour, minute, ampm)    }    /** Parse "shaam N baje" (evening at N, Hindi). */    private fun parseShaamBaje(s: String): Long? {        val match = Regex("""^shaam\s+(\d{1,2})(?::(\d{2}))?\s*(?:baje)?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        return todayAt(hour, minute, "pm") ?: tomorrowAt(hour, minute, "pm")    }    /** Parse "N baje" (today at N, Hindi). */    private fun parseBaje(s: String): Long? {        val match = Regex("""^(\d{1,2})(?::(\d{2}))?\s*baje(?:\s*(am|pm))?$""").find(s)            ?: return null        val hour = match.groupValues[1].toIntOrNull() ?: return null        val minute = match.groupValues[2].toIntOrNull() ?: 0        val ampm = match.groupValues[3].ifBlank { if (hour in 6..11) "am" else "pm" }        return todayAt(hour, minute, ampm) ?: tomorrowAt(hour, minute, ampm)    }    /** Parse standard time formats (12h "7:00 AM" / 24h "19:00"). */    private fun parseStandardTime(s: String): Long? {        // Try "H:mm AM/PM" or "H AM/PM" (12-hour).        val match12 = Regex("""^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$""").find(s)        if (match12 != null) {            val hour = match12.groupValues[1].toIntOrNull() ?: return null            val minute = match12.groupValues[2].toIntOrNull() ?: 0            val ampm = match12.groupValues[3]            return todayAt(hour, minute, ampm) ?: tomorrowAt(hour, minute, ampm)        }        // Try "HH:mm" (24-hour).        val match24 = Regex("""^(\d{1,2}):(\d{2})$""").find(s)        if (match24 != null) {            val hour = match24.groupValues[1].toIntOrNull() ?: return null            val minute = match24.groupValues[2].toIntOrNull() ?: return null            if (hour !in 0..23 || minute !in 0..59) return null            return todayAt24(hour, minute) ?: tomorrowAt24(hour, minute)        }        // Try "H:mm" (12-hour, no AM/PM — assume AM if < 12, else PM).        val matchBare = Regex("""^(\d{1,2}):(\d{2})$""").find(s)        if (matchBare != null) {            val hour = matchBare.groupValues[1].toIntOrNull() ?: return null            val minute = matchBare.groupValues[2].toIntOrNull() ?: return null            if (hour !in 0..23 || minute !in 0..59) return null            val ampm = if (hour in 6..11 || hour == 0) "am" else "pm"            return todayAt(hour, minute, ampm) ?: tomorrowAt(hour, minute, ampm)        }        return null    }    // ─── Calendar helpers ─────────────────────────────────────────────────    /** Compute epoch ms for "today at hour:minute AM/PM" (returns null if past — caller should use tomorrow). */    private fun todayAt(hour: Int, minute: Int, ampm: String): Long? {        val cal = Calendar.getInstance()        cal.set(Calendar.HOUR_OF_DAY, to24Hour(hour, ampm))        cal.set(Calendar.MINUTE, minute)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        val ms = cal.timeInMillis        return if (ms > System.currentTimeMillis()) ms else null    }    /** Compute epoch ms for "tomorrow at hour:minute AM/PM". */    private fun tomorrowAt(hour: Int, minute: Int, ampm: String): Long {        val cal = Calendar.getInstance()        cal.add(Calendar.DAY_OF_MONTH, 1)        cal.set(Calendar.HOUR_OF_DAY, to24Hour(hour, ampm))        cal.set(Calendar.MINUTE, minute)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        return cal.timeInMillis    }    /** Compute epoch ms for "day after tomorrow at hour:minute AM/PM" (parso). */    private fun dayAfterTomorrowAt(hour: Int, minute: Int, ampm: String): Long {        val cal = Calendar.getInstance()        cal.add(Calendar.DAY_OF_MONTH, 2)        cal.set(Calendar.HOUR_OF_DAY, to24Hour(hour, ampm))        cal.set(Calendar.MINUTE, minute)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        return cal.timeInMillis    }    /** 24-hour variant of [todayAt]. */    private fun todayAt24(hour: Int, minute: Int): Long? {        val cal = Calendar.getInstance()        cal.set(Calendar.HOUR_OF_DAY, hour)        cal.set(Calendar.MINUTE, minute)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        val ms = cal.timeInMillis        return if (ms > System.currentTimeMillis()) ms else null    }    /** 24-hour variant of [tomorrowAt]. */    private fun tomorrowAt24(hour: Int, minute: Int): Long {        val cal = Calendar.getInstance()        cal.add(Calendar.DAY_OF_MONTH, 1)        cal.set(Calendar.HOUR_OF_DAY, hour)        cal.set(Calendar.MINUTE, minute)        cal.set(Calendar.SECOND, 0)        cal.set(Calendar.MILLISECOND, 0)        return cal.timeInMillis    }    /** Convert 12-hour + AM/PM to 24-hour. */    private fun to24Hour(hour: Int, ampm: String): Int {        val h = hour.coerceIn(1, 12)        return when (ampm.lowercase()) {            "am" -> if (h == 12) 0 else h            "pm" -> if (h == 12) 12 else h + 12            else -> h        }    }}/** * NOUS — Time Parse Result (sealed). * * Strategy §13: "TimeParser returns TimeParseResult: Success (epoch millis), * AMBIGUOUS ('7am or 7pm?'), FAILED". * * Replaces the previous `Long?` return type which couldn't distinguish * "failed to parse" from "ambiguous — need clarification". */sealed interface TimeParseResult {    /** Successfully parsed — [epochMs] is the target time. */    data class Success(val epochMs: Long) : TimeParseResult    /**     * Ambiguous — the input could be AM or PM. Caller should ask the user     * to clarify using [clarificationPrompt].     */    data class Ambiguous(val clarificationPrompt: String) : TimeParseResult    /** Could not parse — [reason] explains what went wrong. */    data class Failed(val reason: String) : TimeParseResult}